using NuclearOptionObserver;
static class TerrainTests
{
 static void Check(bool v){if(!v)throw new Exception("terrain assertion failed");}
 static TerrainObservation Data(double time,params TerrainPoint[] p)=>new(true,time,p,p.Length);
 public static (string Name,Action Body)[] Cases=>new (string,Action)[]{
  ("water lower surface is valid clear data rather than missing geometry",()=>{var a=new TerrainAdvisor();Check(a.Assess(true,HoldControlTests.Good(),Data(1,new TerrainPoint(0,0),new TerrainPoint(1200,0)),1,out var d,out _)&&!d.Avoiding&&d.Valid);}),
  ("ridge and direct collision samples demand climb and level bank",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();Check(a.Assess(true,f,Data(1,new TerrainPoint(0,0),new TerrainPoint(1000,900)),1,out var d,out _)&&d.Avoiding&&d.VerticalSpeed>0);a.Reset();Check(a.Assess(true,f,Data(2,new TerrainPoint(1200,1000)),2,out d,out _)&&d.Avoiding);}),
  ("terrain clear hysteresis advances only on new sample and returns original target",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();a.Assess(true,f,Data(1,new TerrainPoint(1000,900)),1,out _,out _);var clear=Data(1.2,new TerrainPoint(1000,0));a.Assess(true,f,clear,1.2,out _,out _);for(int i=0;i<10;i++)a.Assess(true,f,clear,1.2,out _,out _);Check(a.Avoiding);a.Assess(true,f,Data(1.4,new TerrainPoint(1000,0)),1.4,out _,out _);Check(a.Avoiding);a.Assess(true,f,Data(1.6,new TerrainPoint(1000,0)),1.6,out var d,out _);Check(!a.Avoiding&&!d.Avoiding);}),
  ("invalid stale nonfinite or truncated terrain data never means clear",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();Check(!a.Assess(true,f,new(false,1,[],0),1,out _,out _));Check(!a.Assess(true,f,Data(1,new TerrainPoint(1,0)),2,out _,out _));Check(!a.Assess(true,f,Data(2,new TerrainPoint(1,float.NaN)),2,out _,out _));Check(!a.Assess(true,f,Data(2),2,out _,out _));}),
  ("avoidance OFF skips invalid sensing and changes only avoidance state",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();a.Assess(true,f,Data(1,new TerrainPoint(1000,900)),1,out _,out _);Check(a.Avoiding);Check(a.Assess(false,f,default,100,out var d,out _)&&d.Valid&&!d.Avoiding&&!a.Avoiding);}),
  ("insufficient climb or airspeed margin is an urgent limitation not fake avoidance",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();Check(!a.Assess(true,f,Data(1,new TerrainPoint(100,2000)),1,out _,out var reason)&&reason.Length>0);f.AirSpeed=72;Check(!a.Assess(true,f,Data(2,new TerrainPoint(1000,900)),2,out _,out _));}),
  ("descent segment hazard has priority even when near below sample is clear",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.VerticalSpeed=-100;Check(a.Assess(true,f,Data(1,new TerrainPoint(0,0),new TerrainPoint(1200,300)),1,out var d,out _)&&d.Avoiding&&d.VerticalSpeed>0);}),
  ("terrain projection uses horizontal ground speed not total HUD speed in descent",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.Altitude=500;f.Speed=200;f.GroundSpeed=100;f.VerticalSpeed=-30;Check(a.Assess(true,f,new(true,0,new[]{new TerrainPoint(1500,0)},1),0,out var d,out _)&&d.Avoiding);}),
  ("response delay includes descent altitude loss before judging recovery feasible",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.VerticalSpeed=-50;f.Speed=158;f.GroundSpeed=150;Check(!a.Assess(true,f,Data(1,new TerrainPoint(300,800)),1,out _,out var why)&&why.StartsWith("URGENT"));}),
  ("hazard inside expired response window is urgent not fabricated half second recovery",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.VerticalSpeed=-50;Check(!a.Assess(true,f,Data(1,new TerrainPoint(150,850)),1,out _,out var why)&&why.StartsWith("URGENT"));Check(a.Assess(false,f,default,100,out var off,out _)&&!off.Avoiding);}),
  ("feasible descent recovery includes response loss and retains bounded climb",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.VerticalSpeed=-20;Check(a.Assess(true,f,Data(1,new TerrainPoint(450,850)),1,out var d,out _)&&d.Avoiding&&Math.Abs(d.VerticalSpeed-20)<.01f);}),
  ("cached forward sample age reduces remaining recovery time",()=>{var a=new TerrainAdvisor();var f=HoldControlTests.Good();f.VerticalSpeed=-50;Check(!a.Assess(true,f,Data(1,new TerrainPoint(375,800)),1.5,out _,out var why)&&why.StartsWith("URGENT"));}),
  ("sensor cadence is bounded and never catches up with a burst",()=>{var s=new TerrainScanSchedule();Check(s.Due(0)&&!s.Due(.1)&&s.Due(.2)&&s.Due(100)&&!s.Due(100)&&!s.Due(double.NaN));s.Reset();Check(s.Due(100));}),
 };
}
